function pairWithSum(nums, target) {
  const seen = new Map() //@init
  for (let i = 0; i < nums.length; i++) { //@loop
    const need = target - nums[i] //@need
    if (seen.has(need)) return [seen.get(need), i] //@found
    seen.set(nums[i], i) //@store
  }
  return [] //@none
}

