function solve(items: number[]): number[] | null {
  const seen = new Map<number, number>() // value -> index (or count, or list)
  for (let i = 0; i < items.length; i++) {
    const want = items[i] // what would complete the answer with this item?
    if (seen.has(want)) {
      return [seen.get(want)!, i] // found it
    }
    seen.set(items[i], i) // remember this item for the steps ahead
  }
  return null // nothing matched
}

